// src/pages/Community.js

import { useNavigate } from "react-router-dom";

const meetings = [
  {
    id: 1,
    title: "노르웨이의 숲 독서모임",
    time: "오늘 19:00",
    members: "6/8명",
    mood: "badge1",
  },

  {
    id: 2,
    title: "데미안 함께 읽기",
    time: "내일 20:00",
    members: "4/6명",
    mood: "badge2",
  },

  {
    id: 3,
    title: "어린왕자 감성모임",
    time: "토요일 18:00",
    members: "5/7명",
    mood: "badge3",
  },
];

function Community() {
  const navigate = useNavigate();

  return (
    <div className="page">
      <div className="top-bar">
        <div className="logo">
          READLY
        </div>
      </div>

      <div className="community-banner">
        ⏰ 모임 시작 10분 전까지
        참여 가능해요
      </div>

      {meetings.map((meeting) => (
        <div
          className="group-card"
          key={meeting.id}
        >
          <div className="group-header">
            <div>
              <div className="group-title">
                {meeting.title}
              </div>

              <div className="group-info">
                {meeting.time}
              </div>
            </div>

            <div className="badge-wrap">
              <div className="badge">
                모임중
              </div>

              <div className={meeting.mood}>
                {meeting.mood ===
                  "badge1" &&
                  "깊게 토론해요"}

                {meeting.mood ===
                  "badge2" &&
                  "부담없이 참여해요"}

                {meeting.mood ===
                  "badge3" &&
                  "함께 이야기해요"}
              </div>
            </div>
          </div>

          <div className="group-footer">
            <span>
              {meeting.members}
            </span>

            <button
              className="join-btn"
              onClick={() =>
                navigate("/meeting", {
                  state: {
                    title:
                      meeting.title,

                    mood:
                      meeting.mood,
                  },
                })
              }
            >
              참여하기
            </button>
          </div>
        </div>
      ))}
    </div>
  );
}

export default Community;
